package dev.incidentai.backend.controller;
import dev.incidentai.backend.dto.*;import dev.incidentai.backend.entity.IncidentStatus;import dev.incidentai.backend.service.IncidentService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/incidents")
public class IncidentController {private final IncidentService service;public IncidentController(IncidentService service){this.service=service;}@PostMapping ResponseEntity<IncidentResponse> create(@Valid @RequestBody IncidentRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@GetMapping List<IncidentResponse> all(@RequestParam(required=false) IncidentStatus status){return service.findAll(status);}@GetMapping("/{id}") IncidentResponse one(@PathVariable Long id){return service.find(id);}@PatchMapping("/{id}/acknowledge") IncidentResponse acknowledge(@PathVariable Long id){return service.acknowledge(id);}@PatchMapping("/{id}/resolve") IncidentResponse resolve(@PathVariable Long id){return service.resolve(id);}}
